internal static partial class FrameScopeReportGenerator
{
    private static string ReportHtmlStyles()
    {
        return @"<style>

:root{color-scheme:dark;--bg:#111318;--panel:#1a1d24;--panel2:#20242d;--line:#30353f;--text:#f0f2f5;--muted:#a8b0bf;--dim:#778194;--accent:#6b9fff;--cyan:#6b9fff;--green:#55d6a0;--yellow:#e9bc6b;--red:#f17c89}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:'Segoe UI','Microsoft YaHei UI',sans-serif;font-size:14px;line-height:1.5;font-variant-numeric:tabular-nums}button,input,select{font:inherit}button{cursor:pointer}button,input,select,a{touch-action:manipulation}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}button:disabled{cursor:not-allowed;opacity:.5}
.shell{max-width:1920px;min-height:100vh;margin:auto;display:grid;grid-template-columns:208px minmax(0,1fr)}.left{position:sticky;top:0;height:100vh;border-right:1px solid #292d36;background:#15171d;padding:30px 16px;display:flex;flex-direction:column;overflow-y:auto}.brand{display:flex;align-items:center;gap:9px;text-decoration:none;color:var(--text);font-size:19px;font-weight:700;letter-spacing:-.5px;white-space:nowrap}.brand-mark{display:grid;place-items:center;background:#648ffa;color:#111722;width:28px;height:30px;border-radius:8px;font-weight:800}.brand-sub{color:var(--muted);font-size:12px;margin:8px 0 38px 38px;letter-spacing:1px}.nav-label,.eyebrow{color:var(--dim);font-size:12px;letter-spacing:1.7px;font-weight:600}.nav-label{margin:0 12px 10px}.tabs{display:flex;flex-direction:column;gap:5px}.tab{border:1px solid transparent;border-radius:8px;background:transparent;color:var(--muted);min-height:43px;text-align:left;padding:10px;font-size:12px;display:flex;align-items:center;gap:9px;transition:background .15s,color .15s}.tab:hover{background:#21252d;color:var(--text)}.tab.active{background:#273348;color:#b2ceff;border-color:#33445f}.nav-index{font-size:12px;opacity:.6;min-width:17px}.tab-disabled{opacity:.65}.nav-help{margin-top:auto;padding:30px 10px 0;color:var(--dim);font-size:12px}.nav-help b{color:var(--muted);font-weight:500}.nav-help p{line-height:2}.nav-help span{display:block;border-top:1px solid #292d36;padding-top:16px;font-size:12px}
.main{min-width:0;padding:32px clamp(20px,2.4vw,44px) 40px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:26px}.game{display:flex;align-items:center;gap:16px;min-width:0}.game>div:last-child{min-width:0}.game-icon{width:52px;height:52px;flex-shrink:0;display:grid;place-items:center;border-radius:13px;background:#263247;border:1px solid #3b4d6b;color:#a4c2ff;font-size:21px;font-weight:700}.game-name{font-size:clamp(22px,2vw,30px);font-weight:650;letter-spacing:-.6px;margin:2px 0 5px;overflow-wrap:anywhere;line-height:1.25}.meta{display:flex;flex-wrap:wrap;gap:5px 18px;font-size:12px;color:var(--muted)}.report-badge{flex-shrink:0;border:1px solid var(--line);border-radius:7px;padding:6px 11px;color:var(--muted);font-size:12px}
.hardware-grid{display:grid;grid-template-columns:1fr 1fr 1.3fr;gap:12px;margin-bottom:18px}.hardware-card{min-width:0;padding:16px 18px;border:1px solid #292e38;border-radius:10px;background:#171a20}.hardware-card h3{font-size:12px;text-transform:uppercase;letter-spacing:1px;font-weight:500;color:var(--dim);margin:0 0 8px}.hardware-name{font-size:12px;font-weight:600;margin-bottom:8px;overflow-wrap:anywhere}.line{display:flex;justify-content:space-between;gap:10px;font-size:12px;line-height:1.8}.line span:first-child{color:var(--muted);flex-shrink:0}.line b{font-weight:400;color:#b7bfcc;text-align:right;overflow-wrap:anywhere;min-width:0}.hardware-memory b{max-height:none}
.gauges{display:grid;grid-template-columns:1.2fr repeat(6,minmax(0,1fr));gap:10px;margin-bottom:28px}.gauge{min-width:0;padding:15px 14px 12px;background:var(--panel);border:1px solid var(--line);border-radius:10px}.gauge:first-child{background:#1b2637;border-color:#334867}.gauge h3{margin:0 0 10px;font-size:12px;color:var(--muted);font-weight:500}.ring{background:none;min-width:0}.ring b{font-size:clamp(21px,2.2vw,31px);font-weight:650;letter-spacing:-.7px;line-height:1.2;overflow-wrap:anywhere}.ring.big b{color:#9dbfff}.ring small{display:block;font-size:12px;color:var(--muted);margin-top:6px}.foot{font-size:12px;color:var(--dim);min-height:15px;margin-top:5px;overflow-wrap:anywhere}
.title{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:15px}.title h2{font-size:21px;font-weight:600;letter-spacing:-.3px;margin:4px 0 0}.title>span{max-width:560px;color:var(--muted);font-size:12px;text-align:right}.alert{display:none;margin:0 0 18px;padding:14px 16px;border:1px solid #70454d;border-radius:9px;background:#332329;color:#f0c1c8;font-size:12px;overflow-wrap:anywhere}.alert.show{display:block}
.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;padding:12px 14px;background:#1a1d24;border:1px solid var(--line);border-bottom:none;border-radius:10px 10px 0 0}.left-tools,.right-tools{display:flex;flex-wrap:wrap;align-items:center;gap:8px;max-width:100%;min-width:0}select,input.search,button.tool{height:33px;max-width:100%;border:1px solid #39404c;border-radius:6px;background:#232731;color:var(--text);padding:0 10px;font-size:12px}select{max-width:min(310px,100%)}.tool:hover{background:#303745;border-color:#5b6e8b}#exportPng{background:#365994;border-color:#4771b5;color:#f0f5ff}#exportPng:hover{background:#4268a7}input.search{width:245px;min-width:0}input::placeholder{color:var(--dim)}.range{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--muted)}.range input{width:100px;min-width:0;accent-color:var(--accent)}.range b{min-width:35px;font-weight:500}#fpsFilterControl{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}#fpsFilterControl[hidden],#fpsFilterInfo[hidden]{display:none}#fpsFilter{accent-color:var(--accent);margin:0}.mode-stats{font-size:12px;color:var(--dim);overflow-wrap:anywhere}
.chart-shell{background:var(--panel);border:1px solid var(--line);border-radius:0 0 10px 10px;overflow:hidden}.chart-scroll{overflow-x:auto;overflow-y:hidden;background:#171b22}.chartbox{position:relative;height:560px;width:100%;min-width:min(900px,100%);resize:both;overflow:hidden;cursor:crosshair}.chartbox.dragging{cursor:grabbing}.chartbox.switching canvas{opacity:.7}canvas{position:absolute;inset:0;width:100%;height:100%;display:block;transition:opacity .12s}#overlay{pointer-events:none}.chart-footer{display:flex;flex-direction:column;gap:10px;padding:12px 18px;border-top:1px solid #2b303a;background:#191c23}.legend{display:flex;flex-wrap:wrap;gap:8px 18px;max-height:100px;overflow:auto;font-size:12px;color:#bdc6d4;min-width:0}.legend span{min-width:0;overflow-wrap:anywhere}.legend .fps-legend-min{color:#009dff}.legend .fps-legend-max{color:#ff3b45}.legend .fps-legend-avg{color:#31e35f}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:6px;vertical-align:1px}.tooltip{position:absolute;pointer-events:none;opacity:0;min-width:min(260px,90%);max-width:min(440px,95%);max-height:min(72vh,520px);overflow:auto;border:1px solid #47536a;border-radius:9px;background:rgba(25,29,38,.98);box-shadow:0 12px 35px #0006;padding:13px 15px;font-size:12px;line-height:1.7;z-index:5;overflow-wrap:anywhere}
.panelgrid{display:grid;grid-template-columns:1.3fr 1fr;gap:16px;margin-top:20px}.card{min-width:0;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:18px 20px}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.section-heading h3{font-size:13px;font-weight:600;margin:0}.section-heading>span{font-size:12px;color:var(--dim)}.rows{display:grid;gap:11px;font-size:12px}.row{display:grid;grid-template-columns:minmax(0,1fr) 70px 86px;gap:10px;align-items:center}.row>span:first-child{overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:var(--muted)}.row>span:nth-child(2){text-align:right}.bar{height:4px;border-radius:8px;background:#2b3340;overflow:hidden}.bar i{display:block;height:100%;background:#628eca;border-radius:8px}#summaryRows{grid-template-columns:1fr}#summaryRows .row{grid-template-columns:minmax(0,1fr) 95px}#summaryRows .bar{display:none}
@media(min-width:1700px){.main{padding-top:40px}.gauges{gap:14px}.gauge{padding:18px}.hardware-card{padding:18px 20px}}
@media(max-width:1250px){.gauges{grid-template-columns:repeat(4,minmax(0,1fr))}.hardware-grid{grid-template-columns:1fr 1fr}.hardware-card:last-child{grid-column:1/-1}.panelgrid{grid-template-columns:1fr}.title>span{max-width:52%}.chartbox{height:480px}}
@media(max-width:900px){.shell{display:block}.left{position:static;height:auto;padding:16px 20px 12px;border-right:0;border-bottom:1px solid var(--line);overflow:visible}.brand{font-size:17px}.brand-sub,.nav-label,.nav-help{display:none}.tabs{flex-direction:row;overflow-x:auto;flex-wrap:nowrap;margin-top:14px;padding:3px 0 6px}.tab{flex-shrink:0;white-space:nowrap;min-height:34px;padding:7px 10px}.nav-index{display:none}.main{padding:22px 20px 30px}.game-name{font-size:24px}.chartbox{height:420px}.topbar{margin-bottom:20px}}
@media(max-width:550px){.main{padding:18px 12px 24px}.left{padding:14px 12px 8px}.report-badge{display:none}.game{gap:12px}.game-icon{width:40px;height:44px}.meta{font-size:12px;gap:3px 10px}.hardware-grid{grid-template-columns:1fr;gap:8px}.hardware-card:last-child{grid-column:auto}.hardware-card{padding:12px 14px}.gauges{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-bottom:22px}.gauge:first-child{grid-column:1/-1}.gauge:first-child .ring b{font-size:34px}.ring b{font-size:26px}.title{display:block}.title>span{display:block;text-align:left;max-width:none;margin-top:6px}.toolbar{padding:10px}.range{width:100%}.range input{flex:1}.right-tools{width:100%}.chartbox{height:360px}.chart-footer{padding:10px 12px}.card{padding:15px}.row{grid-template-columns:minmax(0,1fr) 60px 65px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition:none!important}}

</style>
";
    }
}
